package br.com.brindespro.admin;
import br.com.brindespro.catalog.*;import br.com.brindespro.pricing.*;import br.com.brindespro.quote.*;import org.springframework.transaction.annotation.Transactional;import org.springframework.web.bind.annotation.*;import java.math.BigDecimal;import java.util.*;
@RestController public class AdminConfigController {private final CategoryRepository categories;private final ColorOptionRepository colors;private final MaterialOptionRepository materials;private final AppSettingRepository settings;private final KitRepository kits;private final ProductRepository products;private final CustomerRepository customers;private final PrintingPositionRepository positions;private final ProductionDeadlineRepository deadlines;private final EngravingOptionRepository engravings;public AdminConfigController(CategoryRepository categories,ColorOptionRepository colors,MaterialOptionRepository materials,AppSettingRepository settings,KitRepository kits,ProductRepository products,CustomerRepository customers,PrintingPositionRepository positions,ProductionDeadlineRepository deadlines,EngravingOptionRepository engravings){this.categories=categories;this.colors=colors;this.materials=materials;this.settings=settings;this.kits=kits;this.products=products;this.customers=customers;this.positions=positions;this.deadlines=deadlines;this.engravings=engravings;}
 public record PublicSettings(String whatsappNumber){}@GetMapping("/api/settings/public") public PublicSettings publicSettings(){return new PublicSettings(settings.findById("whatsapp_number").map(s->s.value).orElse(""));}
 public record CategoryInput(Long id,String name,String slug,String imageUrl){}@GetMapping("/api/admin/categories") public List<Category> categories(){return categories.findAll();}@PostMapping("/api/admin/categories") public Category saveCategory(@RequestBody CategoryInput input){if(input.name()==null||input.name().isBlank()||!input.slug().matches("[a-z0-9-]+"))throw new IllegalArgumentException("Categoria inválida.");Category c=input.id()==null?new Category(input.name(),input.slug(),input.imageUrl()):categories.findById(input.id()).orElseThrow();c.name=input.name();c.slug=input.slug();c.imageUrl=input.imageUrl();return categories.save(c);}
 public record ColorInput(Long id,String name,String hex){}@GetMapping("/api/admin/colors") public List<ColorOption> colors(){return colors.findAll();}@PostMapping("/api/admin/colors") public ColorOption saveColor(@RequestBody ColorInput input){if(!input.hex().matches("#[0-9a-fA-F]{6}"))throw new IllegalArgumentException("Cor hexadecimal inválida.");ColorOption c=input.id()==null?new ColorOption(input.name(),input.hex()):colors.findById(input.id()).orElseThrow();c.name=input.name();c.hex=input.hex();return colors.save(c);}
 public record MaterialInput(Long id,String name){}@GetMapping("/api/admin/materials") public List<MaterialOption> materials(){return materials.findAll();}@PostMapping("/api/admin/materials") public MaterialOption saveMaterial(@RequestBody MaterialInput input){MaterialOption m=input.id()==null?new MaterialOption(input.name()):materials.findById(input.id()).orElseThrow();m.name=input.name();return materials.save(m);}
 public record KitInput(Long id,String name,boolean active,BigDecimal discountPercent,List<KitLine> items){}public record KitLine(Long productId,int quantity){}public record KitDto(Long id,String name,boolean active,BigDecimal discountPercent,List<KitLine> items){}private KitDto dto(Kit k){return new KitDto(k.id,k.name,k.active,k.discountPercent,k.items.stream().map(i->new KitLine(i.product.id,i.quantity)).toList());}@GetMapping("/api/kits") public List<KitDto> publicKits(){return kits.findAll().stream().filter(k->k.active).map(this::dto).toList();}@GetMapping("/api/admin/kits") public List<KitDto> kits(){return kits.findAll().stream().map(this::dto).toList();}@PostMapping("/api/admin/kits") @Transactional public KitDto saveKit(@RequestBody KitInput input){if(input.name()==null||input.name().isBlank()||input.discountPercent()==null||input.discountPercent().signum()<0||input.discountPercent().compareTo(BigDecimal.ONE)>=0)throw new IllegalArgumentException("Kit inválido.");Kit k=input.id()==null?new Kit(input.name()):kits.findById(input.id()).orElseThrow();k.name=input.name();k.active=input.active();k.discountPercent=input.discountPercent();k.items.clear();if(input.items()!=null)for(KitLine line:input.items()){if(line.quantity()<1)throw new IllegalArgumentException("Quantidade inválida.");k.items.add(new KitItem(k,products.findById(line.productId()).orElseThrow(),line.quantity()));}return dto(kits.saveAndFlush(k));}
 public record CustomerDto(Long id,String name,String company,String phone,String email){}@GetMapping("/api/admin/customers") public List<CustomerDto> customers(){return customers.findAll().stream().map(c->new CustomerDto(c.id,c.name,c.company,c.phone,c.email)).toList();}
 public record SettingDto(String whatsappNumber){}@GetMapping("/api/admin/settings") public SettingDto settings(){return new SettingDto(publicSettings().whatsappNumber());}@PutMapping("/api/admin/settings") public SettingDto saveSettings(@RequestBody SettingDto input){String number=input.whatsappNumber().replaceAll("[^0-9]","");if(!number.isBlank()&&!number.matches("[0-9]{10,15}"))throw new IllegalArgumentException("Número de WhatsApp inválido.");settings.save(new AppSetting("whatsapp_number",number));return new SettingDto(number);}
 public record Rule(Long id,String name,BigDecimal percent,Integer days,boolean active){}@GetMapping("/api/admin/rules") public Map<String,List<Rule>> rules(){return Map.of("positions",positions.findAll().stream().map(p->new Rule(p.id,p.name,p.percent,null,p.active)).toList(),"deadlines",deadlines.findAll().stream().map(d->new Rule(d.id,d.name,d.percent,d.days,d.active)).toList(),"engravings",engravings.findAll().stream().map(e->new Rule(e.id,e.name,e.percent,null,e.active)).toList());}
 @PutMapping("/api/admin/rules/{type}/{id}") public Rule updateRule(@PathVariable String type,@PathVariable Long id,@RequestBody Rule input){if(input.percent()==null||input.percent().signum()<0||input.percent().compareTo(new BigDecimal("10"))>0)throw new IllegalArgumentException("Percentual inválido.");switch(type){case "positions"->{var p=positions.findById(id).orElseThrow();p.percent=input.percent();p.active=input.active();positions.save(p);return new Rule(id,p.name,p.percent,null,p.active);}case "deadlines"->{var d=deadlines.findById(id).orElseThrow();d.percent=input.percent();d.days=input.days();d.active=input.active();deadlines.save(d);return new Rule(id,d.name,d.percent,d.days,d.active);}case "engravings"->{var e=engravings.findById(id).orElseThrow();e.percent=input.percent();e.active=input.active();engravings.save(e);return new Rule(id,e.name,e.percent,null,e.active);}default->throw new IllegalArgumentException("Tipo de regra inválido.");}}
}
